/**
 * App composer for `App.toUI()`.
 *
 * Walks an `App`'s automations / agents bags and emits a single
 * json-render `SerializedRenderTree` containing a top-level `Card` with
 * a vertical `Stack` of sections — one section per entity kind, each
 * with a heading and either a nested `FlowGraph` (for automations) or a
 * `Grid` of `ActivityNode`s (for agents).
 *
 * Both built deployables (with a `toRenderNode()` method) and pre-loaded
 * `App*` reference shapes are accepted. References render as a single
 * neutral activity node since their internal structure isn't available
 * client-side.
 */
import { activityNode, card, grid, heading, serializeRenderTree, stack, } from "./render-tree.js";
function hasToRenderNode(value) {
    return (typeof value === "object" &&
        value !== null &&
        typeof value.toRenderNode === "function");
}
function entryName(entry, fallback) {
    if (typeof entry === "object" && entry !== null) {
        const named = entry;
        if (typeof named.name === "string" && named.name.length > 0)
            return named.name;
    }
    return fallback;
}
/**
 * Resolve a single bag entry into a `RenderNode`. If the entry is a
 * built deployable (has `toRenderNode`), use its tree; otherwise treat
 * it as a reference and render it as a single colored leaf.
 */
function entryNode(entry, fallbackKey, refKind, refTypeLabel, layout) {
    if (hasToRenderNode(entry) && layout === "graph-stack")
        return entry.toRenderNode();
    return activityNode({
        kind: refKind,
        name: entryName(entry, fallbackKey),
        referenceName: refTypeLabel,
    });
}
function bagSection(title, entries, refKind, refTypeLabel, layout) {
    if (entries.length === 0)
        return [];
    const childNodes = entries.map(([key, entry]) => entryNode(entry, key, refKind, refTypeLabel, layout));
    const section = layout === "grid"
        ? grid({ columns: 3, gap: "md" }, childNodes)
        : stack(childNodes, { direction: "vertical", gap: "md" });
    return [heading(title, { level: 3 }), section];
}
/**
 * Compose an `App` into a single json-render document. The top-level
 * `Card` carries the app name; nested sections render automations as graphs
 * and agents as a 3-column card grid.
 */
export function appToUi(app) {
    const approvalChainEntries = Object.entries(app.approvalChains ?? {});
    const automationEntries = Object.entries(app.automations ?? {});
    const agentEntries = Object.entries(app.agents ?? {});
    const skillEntries = Object.entries(app.agenticSkills ?? {});
    const sections = [
        ...bagSection("Approval Chains", approvalChainEntries, "DEFAULT", "Approval chain ref", "graph-stack"),
        ...bagSection("Automations", automationEntries, "AUTOMATION", "Automation ref", "graph-stack"),
        ...bagSection("Agents", agentEntries, "AGENT", "Agent ref", "grid"),
        ...bagSection("Skills", skillEntries, "DEFAULT", "Skill ref", "grid"),
    ];
    if (sections.length === 0) {
        sections.push(heading("No approval chains, automations, agents, or skills defined.", { level: 4 }));
    }
    const root = card({ title: app.name, ...(app.description != null && { description: app.description }) }, [stack(sections, { direction: "vertical", gap: "lg" })]);
    return serializeRenderTree(root);
}
